import{flow,earnOpening}from './opening-flow.mjs';
import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
import {CORES,SUPPORTS,TECHNIQUE_CATALOG,compileTechnique,defaultHero,payTechnique,selectTargets}from '../mako.js';import{Battle,makeEnemy,encounterEnemies}from '../battle.js?v=5.6.0';import{World}from '../world.js';
const data=JSON.parse(fs.readFileSync(new URL('../world.json',import.meta.url)));const make=()=>{let heroes=[0,1,2].map(id=>defaultHero(id));heroes.forEach((h,i)=>Object.assign(h,{x:i,y:0}));let e=makeEnemy('boss',1,0,true);Object.assign(e,{x:4,y:0});let b=new Battle({heroes,enemies:[e]});heroes.forEach(h=>h.atb=1);return{b,h:heroes[0],e};};
test('all 120 recipes compile with valid costs and effects',()=>{assert.equal(TECHNIQUE_CATALOG.length,120);assert.equal(new Set(TECHNIQUE_CATALOG.map(t=>t.id)).size,120);for(const t of TECHNIQUE_CATALOG){assert.ok(t.cost>0&&t.power>0);assert.ok(t.name.length>3);}assert.equal(compileTechnique('flame','echo',{ap:120}).rank,3);});
test('overdraw consumes HP and rejects unsafe casts without payment',()=>{let h=defaultHero(0);h.mp=0;let t=compileTechnique('flame');assert.ok(payTechnique(h,t));assert.equal(h.hp,180-3*t.cost);h.hp=1;let before=JSON.stringify(h);assert.equal(payTechnique(h,t),false);assert.equal(JSON.stringify(h),before);});
test('link needs partner, consumes partner resources and damages target',()=>{let{b,h,e}=make();for(let a of b.heroes)a.atb=0;h.atb=1;let t=compileTechnique('flame','link');let mp=h.mp;assert.equal(b.command(h.id,'tech',e.id,t),false);assert.equal(h.mp,mp);b.heroes[1].atb=1;assert.ok(b.command(h.id,'tech',e.id,t));assert.equal(b.heroes[1].mp,b.heroes[1].maxMp-4);assert.equal(b.heroes[1].atb,0);assert.ok(e.hp<e.maxHp);});
test('break cancels telegraphs and removes armor',()=>{let{b,h,e}=make();b.planEnemy(e);assert.ok(e.intent);assert.ok(b.command(h.id,'tech',e.id,compileTechnique('earth','break')));assert.equal(e.intent,null);assert.ok(e.status.stagger);assert.ok(e.armor<e.maxArmor);});
test('volt reacts with wet targets',()=>{let a=make(),c=make(),t=compileTechnique('volt');c.e.status.wet=7;a.b.apply(a.h,a.e,t);c.b.apply(c.h,c.e,t);assert.ok(c.e.hp<a.e.hp);});
test('guard restores focus and reduces strain',()=>{let{b,h}=make();h.mp=1;h.strain=80;assert.ok(b.command(h.id,'guard',h.id));assert.equal(h.mp,6);assert.equal(h.strain,58);assert.ok(h.status.guard);});
test('menders repair, alarms reinforce at most twice, guards alternate',()=>{let{b,e}=make();let m=makeEnemy('mender',1,2);m.x=4;m.y=1;b.enemies.push(m);e.hp=50;b.planEnemy(m);assert.equal(m.intent.kind,'repair');b.executeIntent(m,m.intent);assert.ok(e.hp>50);let s=makeEnemy('scout',1,3);s.x=5;s.y=1;b.enemies.push(s);for(let i=0;i<3;i++){b.planEnemy(s);if(s.intent.kind==='alarm')b.executeIntent(s,s.intent);}assert.equal(b.reinforcements,2);let g=makeEnemy('guard',1,4);b.planEnemy(g);assert.equal(g.intent.kind,'guard');b.planEnemy(g);assert.equal(g.intent.kind,'strike');});
test('echo and field survive JSON save/load',()=>{for(const support of['echo','field']){let{b,h,e}=make();assert.ok(b.command(h.id,'tech',e.id,compileTechnique('flame',support)));const snapshot=b.snapshot();let restored=new Battle({heroes:b.heroes.map(h=>({...h})),enemies:[]});restored.restore(snapshot);let before=restored.enemies[0].hp;for(let i=0;i<25;i++)restored.advance(.1);assert.ok(restored.enemies[0].hp<before);}});
test('healing counter restores defender instead of enemy',()=>{let{b,h,e}=make();h.hp=60;b.command(h.id,'tech',h.id,compileTechnique('mend','counter'));let before=e.hp;b.damage(e,h,10);assert.ok(h.hp>60);assert.equal(e.hp,before);});
test('telegraphed circles and lines can be dodged',()=>{let{b,e}=make();let i={shape:'burst',x:0,y:0};assert.ok(b.intentHits(e,i,{x:0,y:0}));assert.equal(b.intentHits(e,i,{x:4,y:4}),false);i={shape:'line',x:3,y:0,fromX:0,fromY:0};assert.equal(b.intentHits(e,i,{x:2,y:3}),false);});
test('expanded scenes preserve 24 guardians and every authored mechanism is reachable',()=>{assert.equal(data.scenes.length,data.campaign.missions.reduce((n,m)=>n+m.rooms.length,0)+1);assert.equal(data.campaign.missions.length,24);assert.equal(data.scenes.flatMap(r=>r.objects).filter(o=>o.type==='boss').length,24);for(const r of data.scenes){let q=[r.arrive],seen=new Set(q.map(p=>p.join(',')));while(q.length){let[x,y]=q.pop();for(let[a,b]of[[x+1,y],[x-1,y],[x,y+1],[x,y-1]])if(r.floor[b]?.[a]==='.'&&!seen.has(a+','+b)){seen.add(a+','+b);q.push([a,b]);}}for(let o of r.objects){let p=o.xy||o.enemies?.[0]?.[1];if(p)assert.ok([-1,0,1].some(dx=>[-1,0,1].some(dy=>seen.has((p[0]+dx)+','+(p[1]+dy)))),`${r.key}: ${o.type}`);}}});
test('opening puzzle choices earn Rook before the service hatch opens',()=>{const h=flow(),w=h.w;h.use(w.objects().find(o=>o.type==='npc'));h.use(w.objects().find(o=>o.type==='portal'));let town=w.scene,hatch=town.objects.find(o=>o.to==='workshop');h.use(hatch);assert.equal(w.scene.location,5);h.use(town.objects.find(o=>o.type==='puzzle'&&o.bit===0));h.choose();assert.equal(w.state.gold,20);h.use(town.objects.find(o=>o.type==='puzzle'&&o.bit===1));h.choose();assert.deepEqual(w.state.party,[0]);h.choose();assert.deepEqual(w.state.party,[0,2]);h.use(hatch);assert.equal(w.scene.key,'workshop');});
test('save roundtrip and all 24 campaign reward transitions reach ending (model only)',()=>{let d;let initial=earnOpening();let w=initial.w;w.callbacks.onDialog=v=>d=v;function drain(){for(let n=0;d&&n<20;n++){let next=d;d=null;if(next.choices)next.choices[0].action();else next.after?.();}}drain();for(let n=1;n<=24;n++){let m=data.campaign.missions[n-1],r=data.scenes.find(r=>r.chapter===n&&r.objects.some(o=>o.type==='boss'));w.state.scene=r.location;w.currentBattle={object:r.objects.find(o=>o.type==='boss'),mission:m,scene:r.location};w.winBattle();drain();assert.ok(w.state.bosses.includes(n));}assert.equal(w.state.complete,true);assert.equal(w.state.chapter,25);assert.equal(w.state.recruited.length,7);let save=w.save();w.restore(save);assert.equal(w.state.complete,true);});
test('all 24 boss configurations can be resolved using legal resource-paying commands',()=>{for(let n=1;n<=24;n++){let hs=[0,1,2].map(id=>defaultHero(id,Math.min(45,3+n)));hs.forEach((h,i)=>{h.x=i;h.y=0;});let es=encounterEnemies(n,true);es.forEach((e,i)=>{e.x=4+i;e.y=0;});let b=new Battle({heroes:hs,enemies:es,chapter:n});for(let i=0;i<15000&&!b.ended;i++){b.advance(.1);for(let h of b.ready){let low=hs.filter(a=>a.hp>0).sort((a,c)=>a.hp/a.maxHp-c.hp/c.maxHp)[0];if(low.hp<low.maxHp*.6)b.command(h.id,'tech',low.id,compileTechnique('mend','burst',{character:h.id}));else if(h.mp<8||h.strain>70)b.command(h.id,'guard',h.id);else b.command(h.id,'tech',b.livingEnemies[0]?.id,compileTechnique('earth','break',{character:h.id,ap:120}));}}assert.equal(b.ended,'win','chapter '+n);}});

import{findPath}from '../navigation.js';test('tap navigation follows collision and cannot cross walls',()=>{let scene={floor:['.....','.###.','.....']};let p=findPath(scene,[0,0],[4,2]);assert.ok(p.length);assert.ok(p.every(([x,y])=>scene.floor[Math.floor(y)][Math.floor(x)]==='.' ));assert.deepEqual(findPath(scene,[0,0],[2,1]),[]);});
